  "Marker": "<template>\n    <ol\n        role=\"list\"\n        style=\"\n            width: min(600px, calc(100vw - 64px));\n            max-width: 100%;\n            margin: 0;\n            padding: 0;\n            list-style: none;\n        \">\n        <li\n            v-for=\"(entry, index) in history\"\n            :key=\"entry.id\"\n            style=\"position: relative\"\n            :style=\"{ paddingBottom: index < history.length - 1 ? '24px' : '0' }\">\n            <span\n                v-if=\"index < history.length - 1\"\n                aria-hidden=\"true\"\n                style=\"\n                    position: absolute;\n                    top: 32px;\n                    bottom: 0;\n                    left: 16px;\n                    border-left: 1px solid var(--ui-border);\n                \" />\n            <Marker>\n                <MarkerIcon :style=\"{ color: entry.color, borderColor: entry.color }\">\n                    <component :is=\"entry.icon\" />\n                </MarkerIcon>\n                <MarkerContent>\n                    <strong>{{ entry.title }}</strong>\n                    <p style=\"color: var(--ui-muted-foreground); margin: 4px 0 8px\">\n                        {{ entry.description }}\n                    </p>\n                </MarkerContent>\n                <MarkerMeta :date=\"entry.date\" :author=\"entry.author\" />\n            </Marker>\n        </li>\n    </ol>\n</template>\n\n<script setup lang=\"ts\">\nimport { IconPackage, IconTruck, IconCheck } from '@tabler/icons-vue';\nimport { Marker, MarkerIcon, MarkerContent, MarkerMeta } from '@rat.md/miru';\n\nconst history = [\n    {\n        id: 'created',\n        icon: IconPackage,\n        color: 'var(--ui-info)',\n        title: 'Order created',\n        description: 'Order SH-2026-001 has been received.',\n        date: '2026-11-27T09:15:00Z',\n        author: 'Sam Taylor',\n    },\n    {\n        id: 'shipped',\n        icon: IconTruck,\n        color: 'var(--ui-primary)',\n        title: 'Out for delivery',\n        description: 'The order is on its way to the customer.',\n        date: '2026-11-27T11:30:00Z',\n        author: 'Alex Morgan',\n    },\n    {\n        id: 'completed',\n        icon: IconCheck,\n        color: 'var(--ui-success)',\n        title: 'Delivery completed',\n        description: 'The customer has received the order.',\n        date: '2026-11-27T14:45:00Z',\n        author: 'Sam Taylor',\n    },\n];\n</script>\n",
