  "FormSectionRenderer": "<template>\n    <FormSectionRenderer :form=\"formController.form\" :section=\"formSections[0]\" />\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue';\nimport { z } from 'zod';\nimport { FormSectionRenderer, defineFormSections, literal } from '@rat.md/miru';\nimport { useForm } from '@rat.md/miru/composables';\n\nconst formController = useForm({\n    schema: z.object({ name: z.string().min(1, 'Enter a studio name.') }),\n    initialValues: { name: 'Miru studio' },\n    submit: '/api/studio',\n    mode: 'json',\n});\nconst formSections = defineFormSections([\n    {\n        id: 'profile',\n        label: literal('Profile'),\n        fields: [\n            {\n                type: 'input',\n                name: 'name',\n                label: literal('Studio name'),\n                required: true,\n                showValidation: true,\n            },\n        ],\n    },\n]);\nconst formFeedback = ref('Local validation demo. No request is sent.');\nasync function validateForm() {\n    await formController.form.validate('submit');\n    formController.form.setFieldMeta('name', (meta) => ({ ...meta, isTouched: true }));\n    formFeedback.value = formController.form.state.isValid\n        ? 'Ready to save.'\n        : 'Check the highlighted field.';\n}\n</script>\n",
