  "EditorFrame": "<template>\n    <EditorFrame\n        v-model=\"frameText\"\n        aria-label=\"Text editor\"\n        :extensions=\"frameExtensions\"\n        counter />\n</template>\n\n<script setup lang=\"ts\">\nimport type { EditorFrameExtension } from '@rat.md/miru';\nimport { IconLetterCaseUpper, IconBrackets, IconRefresh } from '@tabler/icons-vue';\nimport { ref } from 'vue';\nimport { EditorFrame } from '@rat.md/miru';\n\nconst initialFrameText = 'Select some text and try the toolbar commands.';\nconst frameText = ref(initialFrameText);\nconst frameExtensions: EditorFrameExtension[] = [\n    {\n        id: 'demo',\n        commands: [\n            {\n                id: 'uppercase',\n                label: 'Uppercase',\n                icon: IconLetterCaseUpper,\n                run: (api) => api.setValue(api.value.toUpperCase()),\n            },\n            {\n                id: 'wrap',\n                label: 'Wrap selection',\n                icon: IconBrackets,\n                run: (api) => {\n                    const selection = api.getSelection();\n                    return api.replaceSelection(\n                        '[' + selection.value.slice(selection.start, selection.end) + ']',\n                    );\n                },\n            },\n            {\n                id: 'reset',\n                label: 'Reset text',\n                icon: IconRefresh,\n                run: (api) => api.setValue(initialFrameText),\n            },\n        ],\n    },\n];\n</script>\n",
