  "Drawer": "<template>\n    <Drawer>\n        <DrawerTrigger as-child><Button variant=\"outline\">Open a drawer</Button></DrawerTrigger>\n        <DrawerContent>\n            <DrawerHeader>\n                <DrawerTitle>A little more room.</DrawerTitle>\n                <DrawerDescription>Your ideas, within reach.</DrawerDescription>\n            </DrawerHeader>\n            <DrawerFooter>\n                <DrawerClose as-child><Button variant=\"primary\">Done</Button></DrawerClose>\n            </DrawerFooter>\n        </DrawerContent>\n    </Drawer>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n    Drawer,\n    DrawerTrigger,\n    Button,\n    DrawerContent,\n    DrawerHeader,\n    DrawerTitle,\n    DrawerDescription,\n    DrawerFooter,\n    DrawerClose,\n} from '@rat.md/miru';\n</script>\n",
  "Overlay": "<template>\n    <Button variant=\"primary\" @click=\"overlayVisible = true\">Open an overlay</Button>\n    <Overlay\n        v-model:open=\"overlayVisible\"\n        title=\"Your next great interface\"\n        description=\"A responsive surface for focused work.\">\n        <p>Compose your content here.</p>\n    </Overlay>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue';\nimport { Button, Overlay } from '@rat.md/miru';\n\nconst overlayVisible = ref(false);\n</script>\n",
